from itertools import product
from order import *

# every (from, to) pair: allowed iff it is in the table, and a rejection leaves state untouched
for src, dst in product(OrderState, OrderState):
    o = Order(1); o.state = src
    try:
        o.transition_to(dst); ok = True
    except InvalidTransition:
        ok = False
        assert o.state is src and o.history == [OrderState.CREATED]
    assert ok == (dst in TRANSITIONS[src]), (src, dst)

o = Order(2); o.pay(); o.ship(); o.deliver(); o.refund()
assert [s.value for s in o.history] == ["created","paid","shipped","delivered","refunded"] and o.is_terminal
o = Order(3); o.transition_to("cancelled"); assert o.is_terminal
try: o.pay()
except InvalidTransition as e: print("rejected:", e)
try: Order(4).transition_to("bogus")
except ValueError as e: print("rejected:", e)
print("all 36 pairs ok")
